<?php
require_once '../../config/auth.php';
require_once '../../config/database.php';
requireOsisTreasurer();

$department = trim($_GET['jurusan'] ?? '');
$month = max(1, min(12, (int) ($_GET['bulan'] ?? date('n'))));
$year = max(2020, (int) ($_GET['tahun'] ?? date('Y')));
$months = [1=>'Januari',2=>'Februari',3=>'Maret',4=>'April',5=>'Mei',6=>'Juni',7=>'Juli',8=>'Agustus',9=>'September',10=>'Oktober',11=>'November',12=>'Desember'];
$stmt = $pdo->prepare("SELECT c.id, c.nama_kelas, c.tingkat, COUNT(DISTINCT s.id) AS total_siswa, COUNT(DISTINCT CASE WHEN sdp.status = 'lunas' THEN s.id END) AS total_lunas, CASE MAX(CASE WHEN cdc.status = 'diterima' THEN 3 WHEN cdc.status = 'menunggu' THEN 2 WHEN cdc.status = 'ditolak' THEN 1 ELSE 0 END) WHEN 3 THEN 'diterima' WHEN 2 THEN 'menunggu' WHEN 1 THEN 'ditolak' ELSE 'belum_diserahkan' END AS setoran_status, COALESCE(SUM(CASE WHEN sdp.status = 'lunas' THEN sdp.nominal ELSE 0 END), 0) AS total_masuk FROM classes c INNER JOIN students s ON s.kelas_id = c.id LEFT JOIN (SELECT class_id, MAX(id) AS id FROM cash_settings WHERE jenis_kas = 'kelas' AND tahun = ? AND status = 'aktif' GROUP BY class_id) cs ON cs.class_id = c.id LEFT JOIN student_dues d ON d.setting_id = cs.id AND d.jenis_kas = 'kelas' AND d.class_id = c.id AND d.bulan = ? AND d.tahun = ? AND d.status = 'aktif' LEFT JOIN student_due_payments sdp ON sdp.student_id = s.id AND sdp.student_due_id = d.id LEFT JOIN class_due_confirmations cdc ON cdc.class_id = c.id AND cdc.student_due_id = d.id WHERE COALESCE(NULLIF(TRIM(c.jurusan), ''), 'Belum diatur') = ? GROUP BY c.id, c.nama_kelas, c.tingkat ORDER BY FIELD(c.tingkat, 'X', 'XI', 'XII'), c.nama_kelas");
$stmt->execute([$year, $month, $year, $department]);
$classes = $stmt->fetchAll(PDO::FETCH_ASSOC);
$totalSiswa = array_sum(array_map(static fn($class) => (int) $class['total_siswa'], $classes));
$totalLunas = array_sum(array_map(static fn($class) => (int) $class['total_lunas'], $classes));
$totalMasuk = array_sum(array_map(static fn($class) => (float) $class['total_masuk'], $classes));
$setoranDiterima = count(array_filter($classes, static fn($class) => $class['setoran_status'] === 'diterima'));
$persentaseLunas = $totalSiswa > 0 ? round(($totalLunas / $totalSiswa) * 100) : 0;

$pageTitle = 'Rekap Kelas ' . $department;
require_once '../../includes/header.php';
require_once '../../includes/osis_sidebar.php';
?>
<div class="osis-main-content"><header class="osis-topbar"><button class="btn btn-light d-lg-none" id="osisMenuToggle"><i class="bi bi-list"></i></button><div><strong>Rekap Kelas</strong><small class="d-block text-muted"><?= htmlspecialchars($department) ?></small></div><span class="text-muted small"><?= htmlspecialchars($_SESSION['username']) ?></span></header><main class="role-page osis-class-recap-page"><div class="role-wrap"><div class="role-hero osis-class-recap-hero"><div><a href="kelas.php?bulan=<?= $month ?>&tahun=<?= $year ?>" class="osis-class-recap-back"><i class="bi bi-arrow-left"></i> Kas Per Jurusan</a><span class="text-uppercase small">Jurusan</span><h2><?= htmlspecialchars($department) ?></h2><p class="mb-0">Rekap kelas untuk bulan <?= htmlspecialchars($months[$month]) ?> <?= $year ?>.</p></div><div class="osis-class-recap-period"><i class="bi bi-calendar3"></i><?= htmlspecialchars($months[$month]) ?> <?= $year ?></div></div><form class="payment-filter role-card osis-class-recap-filter" method="get"><input type="hidden" name="jurusan" value="<?= htmlspecialchars($department) ?>"><div class="row g-2 align-items-end"><div class="col-sm-5"><label class="form-label">Bulan</label><select name="bulan" class="form-select"><?php foreach ($months as $number => $name): ?><option value="<?= $number ?>" <?= $month === $number ? 'selected' : '' ?>><?= $name ?></option><?php endforeach; ?></select></div><div class="col-sm-5"><label class="form-label">Tahun</label><input name="tahun" type="number" min="2020" value="<?= $year ?>" class="form-control"></div><div class="col-sm-2"><button class="btn btn-primary w-100"><i class="bi bi-arrow-repeat"></i> Tampilkan</button></div></div></form><section class="osis-class-recap-stat-grid"><article class="primary"><span><i class="bi bi-wallet2"></i></span><small>Total masuk</small><strong>Rp <?= number_format($totalMasuk, 0, ',', '.') ?></strong><p>Kas yang telah tercatat</p></article><article><span class="blue"><i class="bi bi-people-fill"></i></span><small>Siswa lunas</small><strong><?= $totalLunas ?> / <?= $totalSiswa ?></strong><p><?= $persentaseLunas ?>% pembayaran lunas</p></article><article><span class="teal"><i class="bi bi-check2-square"></i></span><small>Setoran diterima</small><strong><?= $setoranDiterima ?> / <?= count($classes) ?></strong><p>Kelas telah menyetor ke OSIS</p></article></section><section class="table-card osis-class-recap-table-card"><div class="osis-class-recap-table-head"><div><span><i class="bi bi-list-check"></i> Rekap kelas</span><h4><?= count($classes) ?> kelas di <?= htmlspecialchars($department) ?></h4><p>Pantau pelunasan siswa dan status setoran tiap kelas.</p></div><div class="osis-class-recap-progress"><span>Pelunasan jurusan <strong><?= $persentaseLunas ?>%</strong></span><i><b style="width: <?= $persentaseLunas ?>%"></b></i></div></div><div class="table-responsive"><table class="table align-middle osis-class-recap-table"><thead><tr><th>No.</th><th>Kelas</th><th>Total Siswa</th><th>Sudah Bayar</th><th>Belum Bayar</th><th>Total Masuk</th><th>Status Setoran OSIS</th></tr></thead><tbody><?php foreach ($classes as $index => $class): $total = (int) $class['total_siswa']; $paid = (int) $class['total_lunas']; ?><tr><td class="osis-class-recap-number"><?= $index + 1 ?></td><td><span class="osis-class-recap-name"><i class="bi bi-door-open"></i><strong><?= htmlspecialchars($class['nama_kelas']) ?></strong></span></td><td><?= $total ?></td><td><span class="osis-class-recap-paid"><?= $paid ?></span></td><td><span class="osis-class-recap-unpaid"><?= $total - $paid ?></span></td><td><strong class="osis-class-recap-amount">Rp <?= number_format((float) $class['total_masuk'], 0, ',', '.') ?></strong></td><td><span class="osis-class-recap-status <?= $class['setoran_status'] === 'diterima' ? 'received' : 'unpaid' ?>"><i class="bi <?= $class['setoran_status'] === 'diterima' ? 'bi-check-circle-fill' : 'bi-x-circle-fill' ?>"></i><?= $class['setoran_status'] === 'diterima' ? 'Lunas' : 'Belum lunas' ?></span></td></tr><?php endforeach; ?><?php if (!$classes): ?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada kelas pada jurusan ini.</td></tr><?php endif; ?></tbody></table></div></section></div></main></div>
+<?php require_once '../../includes/footer.php'; ?>
